/**
 * PIXEL CREW — RFC 7807 Problem Details Error Contract
 * 
 * Standardized HTTP problem details for APIs (RFC 7807).
 * Prevents leaking stack traces, database credentials, or internal file paths in production.
 */

export class ErrorContract {
  /**
   * Synthesize TypeScript RFC 7807 Error Classes & Middleware
   * @returns {string} TypeScript Error Contract source
   */
  static generateErrorClasses() {
    return `/**
 * RFC 7807 Problem Details Standard Error System
 * Auto-generated by Pixel Crew Backend Synthesizer
 */

export interface ProblemDetails {
  type: string;
  title: string;
  status: number;
  detail: string;
  instance?: string;
  invalidParams?: Array<{ name: string; reason: string }>;
  timestamp: string;
}

export class AppError extends Error {
  public readonly status: number;
  public readonly type: string;
  public readonly title: string;
  public readonly detail: string;
  public readonly invalidParams?: Array<{ name: string; reason: string }>;

  constructor(status: number, title: string, detail: string, type: string = "about:blank", invalidParams?: Array<{ name: string; reason: string }>) {
    super(detail);
    this.name = this.constructor.name;
    this.status = status;
    this.title = title;
    this.detail = detail;
    this.type = type;
    this.invalidParams = invalidParams;
    Error.captureStackTrace(this, this.constructor);
  }

  public toProblemDetails(instance?: string): ProblemDetails {
    return {
      type: this.type,
      title: this.title,
      status: this.status,
      detail: this.detail,
      instance,
      invalidParams: this.invalidParams,
      timestamp: new Date().toISOString()
    };
  }
}

export class ValidationError extends AppError {
  constructor(detail: string = "Invalid request payload", invalidParams?: Array<{ name: string; reason: string }>) {
    super(422, "Unprocessable Entity", detail, "https://api.pixelcrew.dev/errors/validation-error", invalidParams);
  }
}

export class AuthenticationError extends AppError {
  constructor(detail: string = "Authentication is required to access this resource") {
    super(401, "Unauthorized", detail, "https://api.pixelcrew.dev/errors/authentication-error");
  }
}

export class ForbiddenError extends AppError {
  constructor(detail: string = "You do not have permission to perform this action") {
    super(403, "Forbidden", detail, "https://api.pixelcrew.dev/errors/forbidden-error");
  }
}

export class NotFoundError extends AppError {
  constructor(resource: string = "Resource", id?: string) {
    const detail = id ? \`\${resource} with ID '\${id}' was not found\` : \`\${resource} was not found\`;
    super(404, "Not Found", detail, "https://api.pixelcrew.dev/errors/not-found");
  }
}

export class ConflictError extends AppError {
  constructor(detail: string = "Resource already exists or conflicting state detected") {
    super(409, "Conflict", detail, "https://api.pixelcrew.dev/errors/conflict");
  }
}

export class RateLimitError extends AppError {
  constructor(retryAfterSeconds: number = 60) {
    super(429, "Too Many Requests", \`Rate limit exceeded. Please retry in \${retryAfterSeconds}s\`, "https://api.pixelcrew.dev/errors/rate-limit");
  }
}

export class InternalServerError extends AppError {
  constructor(detail: string = "An unexpected error occurred while processing your request") {
    super(500, "Internal Server Error", detail, "https://api.pixelcrew.dev/errors/internal-server-error");
  }
}

/**
 * Global API Error Response Formatter
 */
export function formatErrorResponse(error: unknown, instancePath?: string): { status: number; body: ProblemDetails } {
  if (error instanceof AppError) {
    return {
      status: error.status,
      body: error.toProblemDetails(instancePath)
    };
  }

  // Hide internal exception details in production
  const isDev = process.env.NODE_ENV !== "production";
  const message = error instanceof Error ? error.message : "Unknown error";
  
  return {
    status: 500,
    body: {
      type: "https://api.pixelcrew.dev/errors/internal-server-error",
      title: "Internal Server Error",
      status: 500,
      detail: isDev ? message : "An internal server error occurred",
      instance: instancePath,
      timestamp: new Date().toISOString()
    }
  };
}
`;
  }
}
